<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter, useRoute } from 'vue-router'
import { http, errorMessage } from '../../api/http'
import { useAuth } from '../../stores/auth'
import type { User } from '../../types'
import { dateTime } from '../../utils/format'
import FormField from '../../components/FormField.vue'
import PasswordField from '../../components/PasswordField.vue'
import LoadingState from '../../components/LoadingState.vue'
const auth = useAuth(), router = useRouter(), route = useRoute()
const loading = ref(true), saving = ref(false), changing = ref(false), error = ref(''), success = ref(''), passwordError = ref('')
const form = reactive({ fullName: '', phoneNumber: '', defaultShippingAddress: '' })
const passwords = reactive({ currentPassword: '', newPassword: '', confirmPassword: '' })
const mismatch = computed(() => !!passwords.confirmPassword && passwords.newPassword !== passwords.confirmPassword)
async function load() { loading.value = true; error.value = ''; try { const { data } = await http.get<User>('/account/profile'); auth.updateUser(data); Object.assign(form, { fullName: data.fullName, phoneNumber: data.phoneNumber, defaultShippingAddress: data.defaultShippingAddress }) } catch(e) { error.value = errorMessage(e) } finally { loading.value = false } }
async function save() { if (saving.value) return; saving.value = true; error.value = ''; success.value = ''; form.fullName = form.fullName.trim().replace(/\s+/g, ' '); if (form.fullName.length < 2) { error.value = 'Họ tên cần từ 2 đến 120 ký tự.'; saving.value = false; return } try { auth.updateUser((await http.put<User>('/account/profile', form)).data); success.value = 'Đã lưu thông tin hồ sơ.' } catch(e) { error.value = errorMessage(e) } finally { saving.value = false } }
async function changePassword() { if (changing.value || mismatch.value) return; if (passwords.currentPassword === passwords.newPassword) { passwordError.value = 'Mật khẩu mới phải khác mật khẩu hiện tại.'; return } changing.value = true; passwordError.value = ''; try { await http.post('/account/change-password', passwords); Object.assign(passwords, { currentPassword: '', newPassword: '', confirmPassword: '' }); auth.logout(); await router.replace({ path: '/login', query: { passwordChanged: '1' } }) } catch(e) { passwordError.value = errorMessage(e) } finally { changing.value = false } }
onMounted(load)
</script>
<template><div class="profile-page" :class="{ 'container page': !route.path.startsWith('/admin') }"><span class="eyebrow">KHÔNG GIAN CỦA BẠN</span><h1>Hồ sơ của tôi</h1><p class="profile-intro">Quản lý thông tin tài khoản và bảo mật của bạn.</p><LoadingState v-if="loading" /><div v-else class="profile-grid"><aside class="panel profile-summary"><span class="profile-avatar">{{ auth.user?.fullName.trim().charAt(0).toUpperCase() }}</span><h2>{{ auth.user?.fullName }}</h2><p>{{ auth.user?.email }}</p><span class="badge paid">{{ auth.user?.role === 'Admin' ? 'Quản trị viên' : 'Khách hàng' }}</span><small v-if="auth.user?.createdAt">Tham gia {{ dateTime(auth.user.createdAt) }}</small></aside><div class="profile-sections"><section class="panel"><h2>Thông tin cá nhân</h2><p v-if="error" class="alert error" role="alert">{{ error }} <button v-if="!form.fullName" type="button" @click="load">Thử lại</button></p><p v-if="success" class="alert success" role="status">{{ success }}</p><form @submit.prevent="save"><FormField label="Họ tên" id="profile-name"><input id="profile-name" v-model="form.fullName" required minlength="2" maxlength="120" autocomplete="name"></FormField><FormField label="Email" id="profile-email" hint="Email chỉ đọc; chưa hỗ trợ thay đổi email."><input id="profile-email" :value="auth.user?.email" type="email" readonly autocomplete="email"></FormField><FormField label="Số điện thoại (không bắt buộc)" id="profile-phone"><input id="profile-phone" v-model="form.phoneNumber" type="tel" maxlength="40" autocomplete="tel"></FormField><FormField label="Địa chỉ nhận hàng mặc định (không bắt buộc)" id="profile-address"><textarea id="profile-address" v-model="form.defaultShippingAddress" rows="3" maxlength="1000" autocomplete="street-address"></textarea></FormField><button class="btn" :disabled="saving">{{ saving ? 'Đang lưu…' : 'Lưu thay đổi' }}</button></form></section><section class="panel"><h2>Đổi mật khẩu</h2><p class="muted">Sau khi đổi mật khẩu, bạn cần đăng nhập lại trên mọi thiết bị.</p><p v-if="passwordError" class="alert error" role="alert">{{ passwordError }}</p><form @submit.prevent="changePassword"><FormField label="Mật khẩu hiện tại" id="current-password"><PasswordField id="current-password" v-model="passwords.currentPassword" autocomplete="current-password" /></FormField><FormField label="Mật khẩu mới" id="new-password" hint="Từ 8 đến 128 ký tự, khác mật khẩu hiện tại."><PasswordField id="new-password" v-model="passwords.newPassword" autocomplete="new-password" /></FormField><FormField label="Xác nhận mật khẩu mới" id="confirm-password"><PasswordField id="confirm-password" v-model="passwords.confirmPassword" :invalid="mismatch" autocomplete="new-password" /><small v-if="mismatch" id="confirm-password-mismatch" class="field-error" role="alert">Mật khẩu xác nhận không khớp.</small></FormField><button class="btn" :disabled="changing || mismatch">{{ changing ? 'Đang đổi mật khẩu…' : 'Đổi mật khẩu' }}</button></form></section></div></div></div></template>
<style scoped>
.profile-intro { margin-bottom:28px; }.profile-grid { display:grid; grid-template-columns:minmax(220px,300px) minmax(0,1fr); gap:24px; }.profile-summary { align-self:start; display:flex; flex-direction:column; gap:16px; overflow-wrap:anywhere; }.profile-summary h2 { font-size:22px; }.profile-avatar { display:flex; align-items:center; justify-content:center; width:72px; height:72px; border-radius:50%; background:#eef3ff; color:#2457d6; font-size:30px; }.profile-sections { display:grid; gap:24px; min-width:0; }.profile-sections .panel { margin:0; }.profile-sections form { margin-top:24px; }.profile-sections h2 { font-size:23px; }.profile-sections input:read-only { background:#f7f8fc; color:#667085; }.profile-page :deep(input),.profile-page textarea { font-size:16px; }@media(max-width:767px) { .profile-grid { grid-template-columns:minmax(0,1fr); }.profile-summary { gap:12px; } }
</style>